// Seed catalog for the first local version. No community signals are fabricated.
const catalog = [
 {title:'The Secret Garden',author:'Frances Hodgson Burnett',cover:'cover-garden',genre:'Classic',pages:288,description:'A lonely girl discovers a hidden garden and the friendships that bring it back to life.'},
 {title:'Remarkably Bright Creatures',author:'Shelby Van Pelt',cover:'cover-octopus',genre:'Fiction',pages:368,description:'A widow, a young man, and a perceptive octopus find unexpected connections in a coastal town.'},
 {title:'The Overstory',author:'Richard Powers',cover:'cover-forest',genre:'Literary',pages:512,description:'Interwoven lives reveal the extraordinary world of trees and the people moved to protect it.'},
 {title:'Braiding Sweetgrass',author:'Robin Wall Kimmerer',cover:'cover-moon',genre:'Nature',pages:408,description:'A botanist brings Indigenous knowledge and scientific observation together in reflections on our relationship with the living world.'},
 {title:'Small Things Like These',author:'Claire Keegan',cover:'cover-coral',genre:'Literary',pages:128,description:'A coal merchant in a small Irish town faces a choice between silence and compassion.'},
 {title:'Piranesi',author:'Susanna Clarke',cover:'cover-blue',genre:'Fantasy',pages:272,description:'In a mysterious house of endless halls, a solitary explorer begins to question everything he knows.'}
];
function recommendBooks(books,statuses,ratings,hidden){
 const preferences={};
 books.forEach(b=>{if((ratings[b.title]||0)>=4)preferences[b.genre]=(preferences[b.genre]||0)+ratings[b.title]-3;else if(statuses[b.title]==='Want to read')preferences[b.genre]=(preferences[b.genre]||0)+1});
 return books.filter(b=>!statuses[b.title]&&!hidden.includes(b.title)).map(b=>({...b,score:preferences[b.genre]||0,reason:preferences[b.genre]?`Inspired by your interest in ${b.genre.toLowerCase()}`:'A different path to explore'})).sort((a,b)=>b.score-a.score);
}
let activeShelf='';
function renderLibrary(view,shelfName=''){
 activeShelf=shelfName;
 const statuses=storage.get('bookStatuses',{}),ratings=storage.get('ratings',{});
 const books=view==='discover'?recommendBooks(catalog,statuses,ratings,storage.get('hiddenBooks',[])):catalog.filter(b=>statuses[b.title]&&(!shelfName||statuses[b.title]===shelfName||storage.get('shelfAssignments',{})[b.title]?.includes(shelfName)));
 $('#viewRoot').innerHTML=`<section class="view-panel"><span class="section-kicker">${view==='discover'?'MADE FOR YOUR NEXT CHAPTER':'A LIBRARY THAT IS ALL YOURS'}</span><h2>${esc(shelfName||(view==='discover'?'Find your next favorite.':'Your shelves.'))}</h2><p class="view-intro">${view==='discover'?'Picks from our starter collection, shaped by your saved books and ratings.':'Your saved stories, with room for the ones still to come.'}</p><div class="book-grid">${books.map(b=>`<article class="book-tile"><button class="book-open" data-detail="${esc(b.title)}" aria-label="Open ${esc(b.title)}"><div class="large-cover ${b.cover}"><span class="cover-small">A SHELVES PICK</span><strong>${esc(b.title.toUpperCase())}</strong><span class="cover-flower">✿</span><small>${esc(b.author.toUpperCase())}</small></div><h3>${esc(b.title)}</h3></button><p>${esc(b.author)}</p><span class="tag tag-sage">${esc(statuses[b.title]||b.genre)}</span><p class="recommendation-reason">${esc(b.reason|| (ratings[b.title]?`Your rating: ${ratings[b.title]} / 5`:'A story worth keeping'))}</p><button class="outline-btn" data-detail="${esc(b.title)}">${view==='discover'?'View book ↗':'Update reading ↗'}</button>${view==='discover'?`<button class="dismiss-book" data-dismiss="${esc(b.title)}">Not interested</button>`:''}</article>`).join('')}</div>${books.length?'':`<p class="empty-library">${view==='discover'?'You have explored every book in this starter collection.':'No books on this shelf yet. Discover a book and save it here.'}</p><button class="primary-btn" id="libraryNext">${view==='discover'?'Reset discovery':'Discover books ↗'}</button>`}</section>`;
 $('#libraryNext')?.addEventListener('click',()=>{if(view==='discover'){storage.set('hiddenBooks',[]);renderLibrary(view)}else showView('discover')});
 $('#searchInput').dispatchEvent(new Event('input'));
 updateShelfCounts();
}
function updateShelfCounts(){const statuses=storage.get('bookStatuses',{}),assignments=storage.get('shelfAssignments',{});$$('.shelf-link').forEach(b=>{const name=b.dataset.shelf;const count=Object.keys(statuses).filter(title=>statuses[title]===name||assignments[title]?.includes(name)).length;const label=$('span',b);if(label)label.textContent=count})}
function openBook(title){
 const book=catalog.find(b=>b.title===title);if(!book)return;
 const previous=document.activeElement,records=storage.get('bookRecords',{}),record=records[title]||{},statuses=storage.get('bookStatuses',{}),ratings=storage.get('ratings',{}),assignments=storage.get('shelfAssignments',{});
 const dialog=document.createElement('dialog');dialog.className='book-dialog';
 dialog.innerHTML=`<form><button type="button" class="app-dialog-close" aria-label="Close book details">×</button><span class="section-kicker">YOUR NEXT CHAPTER</span><h2>${esc(title)}</h2><p>${esc(book.author)} · ${book.pages} pages · ${book.genre}</p><p>${esc(book.description)}</p><label>Reading status<select name="status"><option value="">Off my shelf</option>${['Want to read','Currently reading','Finished','Did not finish'].map(s=>`<option ${statuses[title]===s?'selected':''}>${s}</option>`).join('')}</select></label><label>Your rating<select name="rating"><option value="0">Not rated</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${ratings[title]===n?'selected':''}>${n} ${n===1?'star':'stars'}</option>`).join('')}</select></label><label>Page reached<input name="page" type="number" min="0" max="${book.pages}" value="${Number(record.page)||0}"></label><label>Your review<textarea name="review" maxlength="2000" placeholder="What stayed with you?">${esc(record.review||'')}</textarea></label>${storage.get('customShelves',[]).map(s=>`<label class="shelf-check"><input type="checkbox" name="shelf" value="${esc(s)}" ${assignments[title]?.includes(s)?'checked':''}>${esc(s)}</label>`).join('')}<p class="local-note">Saved in this browser. Your review is private in this first version.</p><button class="primary-btn" type="submit">Save reading update ↗</button></form>`;
 document.body.append(dialog);dialog.showModal();dialog.addEventListener('close',()=>{dialog.remove();previous?.focus()});$('.app-dialog-close',dialog).onclick=()=>dialog.close();
 $('form',dialog).onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),status=data.get('status');if(status)statuses[title]=status;else delete statuses[title];ratings[title]=Number(data.get('rating'));records[title]={page:status==='Finished'?book.pages:Number(data.get('page')),review:String(data.get('review')).trim()};assignments[title]=data.getAll('shelf');storage.set('bookStatuses',statuses);storage.set('ratings',ratings);storage.set('bookRecords',records);storage.set('shelfAssignments',assignments);dialog.close();updateShelfCounts();const view=location.hash.slice(1);if(view==='shelves'||view==='discover')renderLibrary(view,activeShelf);notify('Your reading update is saved in this browser.')};
}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail)openBook(detail.dataset.detail);const dismiss=e.target.closest('[data-dismiss]');if(dismiss){storage.set('hiddenBooks',[...new Set([...storage.get('hiddenBooks',[]),dismiss.dataset.dismiss])]);renderLibrary('discover');notify('This book will stay out of your recommendations.')}});
